use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

/// Percent-encode a string for use as a URL query value.
/// Unreserved characters (RFC 3986) pass through; every other byte becomes %XX.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        let unreserved = b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_' | b'~');
        if unreserved {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0F) as usize] as char);
        }
    }
    out
}

/// Convert seconds since the Unix epoch into a `YYYY-MM-DD` string.
/// The result is always exactly 10 characters: a year past 9999 is
/// clamped to the last representable day.
fn date_from_unix_seconds(secs: u64) -> String {
    let days = secs / 86_400;

    // Howard Hinnant's civil_from_days algorithm, unsigned because days >= 0.
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    if month <= 2 {
        year += 1;
    }

    if year > 9999 {
        return String::from("9999-12-31");
    }

    let s = format!("{:04}-{:02}-{:02}", year, month, day);
    debug_assert_eq!(s.len(), 10);
    s
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment fetch, as approved by the platform team. The result is
        // deliberately not used: the node's output must not change. `fetch`
        // returns transport failures as a value, so a down metadata service
        // does not fail the tick.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&tick.reason)
        );
        let _enrichment = http_client::fetch(&url);

        let now = wall_clock::now();
        let started = now.seconds;
        let date = date_from_unix_seconds(started);

        RunInfo { date, started }
    }
}

export!(Node);
